import { forwardRef, type HTMLAttributes, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../hooks/use-isomorphic-layout-effect"
import { useComposedRefs } from "../utils/compose-refs"
import { cx } from "../utils/cx"
import { supportsPopover } from "../utils/env"

export type LayerProps = HTMLAttributes<HTMLDivElement>

/**
 * A floating surface promoted to the browser top layer through the Popover API. It escapes
 * `overflow` clipping and stacking contexts without a portal, so it keeps inheriting theme
 * variables from where it is rendered. Older browsers fall back to `position: fixed` + z-index.
 */
export const Layer = forwardRef<HTMLDivElement, LayerProps>(
  ({ className, ...props }, forwardedRef) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)

    useIsomorphicLayoutEffect(() => {
      const node = local.current
      if (!node || !supportsPopover()) return
      node.showPopover()
      return () => {
        if (node.matches(":popover-open")) node.hidePopover()
      }
    }, [])

    return (
      <div
        ref={ref}
        popover="manual"
        className={cx("kg-layer", className)}
        {...props}
      />
    )
  },
)

Layer.displayName = "Layer"

import {
  Children,
  cloneElement,
  forwardRef,
  type HTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  version,
} from "react"
import { composeRefs } from "../utils/compose-refs"
import { mergeProps } from "../utils/merge-props"

const major = Number.parseInt(version, 10)

// React 19 moved `ref` onto props; reading `element.ref` there logs a deprecation warning.
const getElementRef = (element: ReactElement): Ref<unknown> | undefined =>
  major >= 19
    ? (element.props as { ref?: Ref<unknown> }).ref
    : (element as unknown as { ref?: Ref<unknown> }).ref

export interface SlotProps extends HTMLAttributes<HTMLElement> {
  children?: ReactNode
}

/** Renders its only child with the slot's props merged in. Powers every `asChild` prop. */
export const Slot = forwardRef<HTMLElement, SlotProps>(
  ({ children, ...props }, ref) => {
    const child = Children.only(children)
    if (!isValidElement(child)) return null
    return cloneElement(child, {
      ...mergeProps(props, child.props as Record<string, unknown>),
      ref: composeRefs(ref, getElementRef(child)),
    } as Record<string, unknown>)
  },
)

Slot.displayName = "Slot"

"use client"

import { createContext } from "react"

/** `user` follows the OS setting; `always` forces reduced motion for the subtree. */
export type ReducedMotionPreference = "user" | "always"

export const MotionContext = createContext<ReducedMotionPreference>("user")

import { type MutableRefObject, type Ref, type RefCallback, useCallback } from "react"

type PossibleRef<T> = Ref<T> | undefined

const assignRef = <T>(ref: PossibleRef<T>, value: T | null) => {
  if (typeof ref === "function") ref(value)
  else if (ref) (ref as MutableRefObject<T | null>).current = value
}

export const composeRefs =
  <T>(...refs: PossibleRef<T>[]): RefCallback<T> =>
  (node) => {
    for (const ref of refs) assignRef(ref, node)
  }

export const useComposedRefs = <T>(...refs: PossibleRef<T>[]): RefCallback<T> =>
  useCallback(composeRefs(...refs), refs)

"use client"

import { useCallback, useEffect, useRef, useState } from "react"

/** Writes to the clipboard, falling back to a hidden textarea where the async API is blocked. */
export const copyText = async (text: string): Promise<boolean> => {
  try {
    if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    // Permission denied or insecure context: try the legacy path below.
  }
  if (typeof document === "undefined") return false
  const area = document.createElement("textarea")
  area.value = text
  area.setAttribute("readonly", "")
  area.style.position = "fixed"
  area.style.opacity = "0"
  document.body.appendChild(area)
  area.select()
  let ok = false
  try {
    ok = document.execCommand("copy")
  } catch {
    ok = false
  }
  area.remove()
  return ok
}

/** `copied` flips true for `resetMs` after a successful copy, for the button's confirmation. */
export const useCopy = (resetMs = 1600) => {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  const copy = useCallback(
    async (text: string) => {
      const ok = await copyText(text)
      if (!ok) return false
      setCopied(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), resetMs)
      return true
    },
    [resetMs],
  )
  return { copied, copy }
}

export type ClassValue = string | number | false | null | undefined | ClassValue[]

export const cx = (...values: ClassValue[]): string => {
  let out = ""
  for (const value of values) {
    if (!value) continue
    const part = Array.isArray(value) ? cx(...value) : String(value)
    if (part) out = out ? `${out} ${part}` : part
  }
  return out
}

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), max)

export const lerp = (from: number, to: number, t: number): number =>
  from + (to - from) * t

/** Maps `value` from one range onto another without clamping. */
export const remap = (
  value: number,
  inMin: number,
  inMax: number,
  outMin: number,
  outMax: number,
): number => outMin + ((value - inMin) / (inMax - inMin || 1)) * (outMax - outMin)

export const roundToStep = (value: number, step: number, origin = 0): number => {
  const decimals = (String(step).split(".")[1] ?? "").length
  return Number((Math.round((value - origin) / step) * step + origin).toFixed(decimals))
}

import type { CSSProperties } from "react"
import { cx } from "./cx"

type AnyProps = Record<string, unknown>

const isHandler = (
  key: string,
  value: unknown,
): value is (...args: unknown[]) => void =>
  /^on[A-Z]/.test(key) && typeof value === "function"

/** Merges slot props onto child props: handlers chain (child first), classes join, styles spread. */
export const mergeProps = (slot: AnyProps, child: AnyProps): AnyProps => {
  const merged: AnyProps = { ...slot, ...child }
  for (const key of Object.keys(slot)) {
    const slotValue = slot[key]
    const childValue = child[key]
    if (isHandler(key, slotValue) && isHandler(key, childValue)) {
      merged[key] = (...args: unknown[]) => {
        childValue(...args)
        const event = args[0] as { defaultPrevented?: boolean } | undefined
        if (!event?.defaultPrevented) slotValue(...args)
      }
    } else if (key === "className") {
      merged[key] = cx(slotValue as string, childValue as string)
    } else if (key === "style") {
      merged[key] = {
        ...(slotValue as CSSProperties),
        ...(childValue as CSSProperties),
      }
    }
  }
  return merged
}

export interface MoneyFormatOptions {
  currency?: string
  locale?: string | undefined
  /** Drop `.00` on whole amounts. */
  trimZeros?: boolean
  display?: "symbol" | "narrowSymbol" | "code" | "name"
}

const cache = new Map<string, Intl.NumberFormat>()

export const getMoneyFormatter = ({
  currency = "USD",
  locale,
  trimZeros = false,
  display = "symbol",
}: MoneyFormatOptions = {}): Intl.NumberFormat => {
  const key = `${locale ?? ""}|${currency}|${trimZeros}|${display}`
  let formatter = cache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      currencyDisplay: display,
      ...(trimZeros ? { trailingZeroDisplay: "stripIfInteger" } : {}),
    } as Intl.NumberFormatOptions)
    cache.set(key, formatter)
  }
  return formatter
}

export const formatMoney = (amount: number, options?: MoneyFormatOptions): string =>
  getMoneyFormatter(options).format(amount)

/** Whole-number percentage saved, or 0 when there is no discount. */
export const discountPercent = (
  amount: number,
  compareAt: number | undefined,
): number =>
  compareAt && compareAt > amount
    ? Math.round(((compareAt - amount) / compareAt) * 100)
    : 0

import { type ClassValue, cx } from "./cx"

type VariantMap = Record<string, Record<string, ClassValue>>

type OptionKey<T> = T extends "true" | "false" ? boolean | T : T

export type VariantChoices<V extends VariantMap> = {
  [K in keyof V]?: OptionKey<keyof V[K] & string>
}

export interface VariantsConfig<V extends VariantMap> {
  base?: ClassValue
  variants: V
  defaults?: VariantChoices<V>
  /** Extra classes when every listed variant matches. */
  compound?: (VariantChoices<V> & { class: ClassValue })[]
}

export type VariantFn<V extends VariantMap> = (
  props?: VariantChoices<V> & { className?: ClassValue },
) => string

/** The props a `variants()` function accepts, for a component's prop interface. */
export type VariantProps<F> = F extends VariantFn<infer V> ? VariantChoices<V> : never

/**
 * Typed class recipes without a runtime dependency: option names are inferred from the
 * config, so `button({ size: "xl" })` is a type error when `xl` isn't defined.
 */
export const variants =
  <V extends VariantMap>(config: VariantsConfig<V>): VariantFn<V> =>
  (props = {}) => {
    const picked: Record<string, string | undefined> = {}
    for (const key of Object.keys(config.variants)) {
      const value = props[key] ?? config.defaults?.[key]
      picked[key] = value === undefined ? undefined : String(value)
    }
    const classes: ClassValue[] = [config.base]
    for (const [key, value] of Object.entries(picked)) {
      if (value !== undefined) classes.push(config.variants[key]?.[value])
    }
    for (const { class: extra, ...when } of config.compound ?? []) {
      const matches = Object.entries(when).every(
        ([key, value]) => picked[key] === String(value),
      )
      if (matches) classes.push(extra)
    }
    classes.push(props.className)
    return cx(...classes)
  }
